let __v_741 = pyrt::literals::decode("{\"$tuple\":[\"Nothing has to be sorted today. When you are ready it is the register office first - within five days in England and Wales - and then the funeral director, who takes it from there and tells you what to bring. Ask someone to sit with you for the forms.\",\"The practical list is shorter than it looks: the doctor or coroner gives you the medical certificate, you register the death at the local register office, and the funeral director handles what comes next. Tell Us Once covers the tax office, the council and benefits in one go. Everything else can wait.\",\"Take it in the order it comes. Register the death - five days, in England and Wales - and the register office gives you the certificates for the bank and the insurers and a Tell Us Once code. The rest of it, the house and the belongings and the letters, none of that is this week's job.\"]}")?;
frame.store("FIRST_DAYS_PERSON", __v_741.clone())?;
