frame.store("_the_give_up_without_a_care_word", { let __signature_832 = Signature { name: "_the_give_up_without_a_care_word".into(), positional: vec!["tight".into(),"who".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_834 = Value::dict(); __attrs_834.dict_set(Value::from("__doc__"), Value::from("True for the give-up that names a person but no doctor, else False.\n\n    \"they said there is nothing more they can do for her\" has the shape and the person but none of\n    the words `CARE_WHO` wants, so it stayed small talk while the same sentence with \"the doctor\"\n    in front of it was read. Somebody said it, and it is about a third person: that is the news.\n    \"My boss said theres nothing more he can do for me\" is the speaker's own job, which the care\n    words cover when it is care at all, and an institution saying it about a pupil or a tenant is\n    an institution's answer, so neither is here.\n    "))?; __attrs_834.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_835 = Value::dict(); __attrs_834.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_831 = Frame::module(frame.globals.clone()); let mut __function_833 = NativeFunction::qualified_with_origin("_the_give_up_without_a_care_word".into(), "_the_give_up_without_a_care_word".into(), "bot.compose.loss".into(), __attrs_834, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/compose/loss.py", first: 1154, last: 1168, qualname: "_the_give_up_without_a_care_word" }, closure: __closure_831.clone(), freevars: vec![] }, move |rt, args| __py_11::_the_give_up_without_a_care_word(rt, __closure_831.clone(), &__signature_832, args)); __function_833 })?;
let __v_836 = { let __v_837 = frame.load(rt, "SOMEONE_DYING")?; let __v_838 = pyrt::literals::decode("{\"$tuple\":[\"I'm sorry. That's a hard thing to be living with - is there help coming in, or is most of it on you?\",\"I'm sorry. It is happening now rather than after, and that is the part nobody prepares you for. Who is looking after you while you look after them?\"]}")?; pyrt::ops::add(&__v_837, &__v_838)? };
