let __v_856 = pyrt::literals::decode("{\"$tuple\":[\"Keep it short and warm: \\\"I'm so sorry for your loss. Thinking of you and your family.\\\" If you knew them, add one small memory — that is the part people keep.\",\"Two or three lines is plenty: name the person, say you are sorry, and add a practical offer — a meal, a lift, a hand with the children.\"]}")?;
