let __v_857 = pyrt::literals::decode("{\"$tuple\":[\"That is normal after a loss, and it eases slowly for most people. If it is still this heavy, your GP is the right person to talk to.\",\"Most people find the same, and it does get easier. Be gentle with yourself — and see your GP if it has not lifted.\",\"That is part of grief for most people. If it stays like this, tell your GP; there is real help for it.\"]}")?;
frame.store("GRIEF_REPLIES", __v_857.clone())?;
let __v_858 = pyrt::literals::decode("{\"$tuple\":[\"It does get easier, and slowly. Losing a {animal} takes something out of every day, so the quiet is loudest in the first weeks; if it is still this heavy after a month, your GP is the right person to talk to.\",\"It's real grief, and it eases the same way a person's does - slowly. Losing {article} {animal} leaves a gap in the day, so be gentle with yourself, and see your GP if it has not lifted in a few weeks.\",\"Most people find it eases, and no timetable is right. If it stays this heavy, tell your GP: grief for {article} {animal} counts, and there is real help for it.\"]}")?;
