let __v_859 = pyrt::literals::decode("{\"$tuple\":[\"Go if you can, even just for the service: turning up matters far more than anything you say. Take a card, say the plain thing, and leave when you need to.\",\"If you can make it, go — families remember who came. You don't have to speak; sitting with them is the thing.\"]}")?;
