let __v_860 = pyrt::literals::decode("{\"$tuple\":[\"Cremation usually comes out cheaper than burial: the plot, the grave being dug and often a headstone are what the difference is made of. Ask two funeral directors for a written, itemised quote and compare the coffin, the cars and the cremation fee as separate lines.\",\"Cremation, yes - a burial adds the plot, the digging and usually a headstone, and that is where the difference is. The rest of the bill is much the same either way, so ask for the itemised quote and look at the coffin first.\",\"A cremation with no service is the cheapest of the lot, and a burial is the dearest: the plot and the headstone are the difference. Prices move a lot by area, so get two itemised quotes in writing before you decide.\"]}")?;
